import { Component, DOCUMENT, computed, effect, inject } from '@angular/core';
import { RouterOutlet } from '@angular/router';
import { HwButtonDirective, HwPortalFooterComponent, HwPortalHeaderComponent, HwSwitchComponent } from '@hawiyah/angular';
import { Prefs } from './prefs';

const REPO = 'https://github.com/MohamedEmbarak/hawiyah';

@Component({
  selector: 'app-root',
  imports: [RouterOutlet, HwPortalHeaderComponent, HwPortalFooterComponent, HwButtonDirective, HwSwitchComponent],
  styleUrl: './app.css',
  template: `
    <hw-portal-header brand="Hawiyah" [homeHref]="href('/')" mainId="main-content" [links]="links()"
      [skipLabel]="prefs.t('Skip to content', 'انتقل إلى المحتوى')" [menuLabel]="prefs.t('Menu', 'القائمة')"
      [navigationLabel]="prefs.t('Main navigation', 'التنقل الرئيسي')">
      <img hwBrand class="mark" [src]="prefs.mode() === 'dark' ? '/brand/hawiyah-wordmark-white.svg' : '/brand/hawiyah-wordmark.svg'"
        alt="هوية" lang="ar" width="144" height="112">
      <div class="prefs" role="group" [attr.aria-label]="prefs.t('Page preferences', 'تفضيلات الصفحة')">
        <button hwButton variant="secondary" size="sm" type="button" [attr.lang]="prefs.lang() === 'ar' ? 'en' : 'ar'" (click)="switchLanguage()">{{ prefs.lang() === 'ar' ? 'English' : 'العربية' }}</button>
        <hw-switch controlId="page-rtl" [label]="prefs.t('Right to left', 'من اليمين إلى اليسار')" [value]="prefs.dir() === 'rtl'" (valueChange)="prefs.set(prefs.lang(), $event ? 'rtl' : 'ltr', prefs.mode())" />
        <hw-switch controlId="page-dark" [label]="prefs.t('Dark mode', 'الوضع الداكن')" [value]="prefs.mode() === 'dark'" (valueChange)="prefs.set(prefs.lang(), prefs.dir(), $event ? 'dark' : 'light')" />
      </div>
    </hw-portal-header>
    <router-outlet />
    <hw-portal-footer brand="هوية · Hawiyah"
      [description]="prefs.t('Hawiyah is maintained independently and is not an official DGA product.', 'تُدار هوية بصورة مستقلة، وليست منتجًا رسميًا لهيئة الحكومة الرقمية.')"
      [copyright]="prefs.t('Version 0.2.1. Licensed under the Apache License 2.0.', 'الإصدار 0.2.1. مرخّصة برخصة Apache 2.0.')"
      [groups]="footerGroups()" [legalLinks]="legal()"
      [legalLinksLabel]="prefs.t('Licence and notices', 'الترخيص والإشعارات')"
      [externalLabel]="prefs.t('opens in a new window', 'يفتح في نافذة جديدة')" />
  `,
})
export class App {
  readonly prefs = inject(Prefs);
  private readonly doc = inject(DOCUMENT);

  readonly query = computed(() => `?lang=${this.prefs.lang()}&dir=${this.prefs.dir()}&mode=${this.prefs.mode()}`);
  readonly links = computed(() => [
    { label: this.prefs.t('Components', 'المكوّنات'), href: this.href('/components') },
    { label: this.prefs.t('Templates', 'القوالب'), href: this.href('/templates') },
    { label: this.prefs.t('Repository', 'المستودع'), href: REPO },
  ]);
  readonly footerGroups = computed(() => [
    { title: this.prefs.t('Guide', 'الدليل'), links: [
      { label: this.prefs.t('Components', 'المكوّنات'), href: this.href('/components') },
      { label: this.prefs.t('Templates', 'القوالب'), href: this.href('/templates') },
    ] },
    { title: this.prefs.t('Project', 'المشروع'), links: [
      { label: this.prefs.t('Repository on GitHub', 'المستودع على GitHub'), href: REPO, external: true },
      { label: this.prefs.t('Packages on npm', 'الحزم على npm'), href: 'https://www.npmjs.com/search?q=%40hawiyah', external: true },
    ] },
  ]);
  readonly legal = computed(() => [
    { label: this.prefs.t('Apache License 2.0', 'رخصة Apache 2.0'), href: `${REPO}/blob/main/LICENSE`, external: true },
    { label: this.prefs.t('Notices', 'الإشعارات'), href: `${REPO}/blob/main/NOTICE`, external: true },
  ]);

  constructor() {
    // Keep the address in step with the preferences so that reloads and in-page anchors keep them.
    effect(() => {
      const view = this.doc.defaultView;
      if (view) view.history.replaceState(view.history.state, '', view.location.pathname + this.query() + view.location.hash);
    });
  }
  href(path: string): string { return path + this.query(); }
  switchLanguage(): void {
    const lang = this.prefs.lang() === 'ar' ? 'en' : 'ar';
    this.prefs.set(lang, lang === 'ar' ? 'rtl' : 'ltr', this.prefs.mode());
  }
}

