import { Component, DOCUMENT, inject, input, signal } from '@angular/core';
import { HwButtonDirective } from '@hawiyah/angular';
import { Prefs } from './prefs';

/** Code sample. The packages have no code-block component (recorded as a gap): plain pre/code with token-only styling. */
@Component({
  selector: 'app-code',
  imports: [HwButtonDirective],
  styleUrl: './code.css',
  template: `
    <div class="block" [class.with-copy]="copy()">
      <pre class="code" dir="ltr" lang="en" translate="no"><code>{{ code() }}</code></pre>
      @if (copy()) {
        <button hwButton variant="secondary" size="sm" type="button" (click)="copyText()">{{ copied() ? prefs.t('Copied', 'تم النسخ') : prefs.t('Copy', 'نسخ') }}<span class="hw-sr-only">: {{ copyName() }}</span></button>
        <span class="hw-sr-only" role="status">{{ copied() ? prefs.t('Copied to the clipboard.', 'تم النسخ إلى الحافظة.') : '' }}</span>
      }
    </div>
  `,
})
export class Code {
  readonly code = input.required<string>();
  readonly copy = input(false);
  /** What the copy button copies, for its accessible name. */
  readonly copyName = input('');
  readonly prefs = inject(Prefs);
  readonly copied = signal(false);
  private readonly doc = inject(DOCUMENT);

  async copyText(): Promise<void> {
    try {
      await this.doc.defaultView?.navigator.clipboard.writeText(this.code());
      this.copied.set(true);
      this.doc.defaultView?.setTimeout(() => this.copied.set(false), 4000);
    } catch { this.copied.set(false); }
  }
}

