import { Component, computed, effect, inject, signal, untracked } from '@angular/core';
import {
  HwCardComponent, HwContainerComponent, HwDescriptionListComponent, HwDividerComponent, HwLinkComponent,
  HwButtonDirective, HwTabComponent, HwTabsComponent, HwToggleGroupComponent,
} from '@hawiyah/angular';
import { Code } from './code';
import { Pane, type Density, type PaneState } from './pane';
import { Prefs, type Dir, type Lang, type Mode } from './prefs';

type PaneId = 'a' | 'b';
const REPO = 'https://github.com/MohamedEmbarak/hawiyah';
const ltr = (text: string) => `⁦${text}⁩`;

const STATEMENT: Record<Lang, { title: string; body: string }> = {
  en: {
    title: 'Hawiyah is a UI component library built to comply with the DGA Platforms Code.',
    body: 'Language, direction, colour mode and density are four separate attributes. Arabic and English run through the same components, tokens and styles.',
  },
  ar: {
    title: 'هوية مكتبة مكوّنات واجهات مبنية للامتثال لكود المنصات الصادر عن هيئة الحكومة الرقمية.',
    body: 'اللغة والاتجاه ونمط الألوان والكثافة أربع سمات مستقلة. تعمل العربية والإنجليزية بالمكوّنات ورموز التصميم والأنماط نفسها.',
  },
};

interface Framework { id: string; name: string; install: string; stylesFile: [string, string]; styles: string; use: string }
const FRAMEWORKS: readonly Framework[] = [
  {
    id: 'angular', name: 'Angular', install: 'npm install @hawiyah/styles @hawiyah/angular',
    stylesFile: ['In src/styles.css', 'في الملف src/styles.css'], styles: `@import '@hawiyah/styles/styles.css';`,
    use: `import { Component } from '@angular/core';
import { HwButtonDirective, HwTextFieldComponent } from '@hawiyah/angular';

@Component({
  selector: 'app-example',
  imports: [HwButtonDirective, HwTextFieldComponent],
  template: \`
    <hw-text-field label="Full name" name="name" />
    <button hwButton type="submit">Continue</button>
  \`,
})
export class Example {}`,
  },
  {
    id: 'react', name: 'React', install: 'npm install @hawiyah/styles @hawiyah/react',
    stylesFile: ['In the entry module', 'في ملف المدخل'], styles: `import '@hawiyah/styles/styles.css';`,
    use: `import { Button, TextField } from '@hawiyah/react';

export function Example() {
  return (
    <form>
      <TextField label="Full name" name="name" />
      <Button type="submit">Continue</Button>
    </form>
  );
}`,
  },
  {
    id: 'vue', name: 'Vue', install: 'npm install @hawiyah/styles @hawiyah/vue',
    stylesFile: ['In the entry module', 'في ملف المدخل'], styles: `import '@hawiyah/styles/styles.css';`,
    use: `<script setup lang="ts">
import { ref } from 'vue';
import { Button, TextField } from '@hawiyah/vue';
const name = ref('');
</script>

<template>
  <TextField v-model="name" label="Full name" name="name" />
  <Button type="submit">Continue</Button>
</template>`,
  },
  {
    id: 'vanilla', name: 'JavaScript', install: 'npm install @hawiyah/styles @hawiyah/vanilla',
    stylesFile: ['In the entry module', 'في ملف المدخل'], styles: `import '@hawiyah/styles/styles.css';`,
    use: `import { enhance } from '@hawiyah/vanilla';

// Adds behaviour to semantic HTML that already carries hw- classes.
const destroy = enhance(document.querySelector('#application'));
// Before the subtree is removed:
destroy();`,
  },
];

/** Landing page, direction C: two languages, one system. */
@Component({
  selector: 'app-home',
  imports: [HwContainerComponent, HwDividerComponent, HwToggleGroupComponent, HwButtonDirective, HwTabsComponent, HwTabComponent,
    HwDescriptionListComponent, HwCardComponent, HwLinkComponent, Pane, Code],
  styleUrl: './home.css',
  template: `
    <main id="main-content" tabindex="-1" class="page">
      <hw-container>
        <div class="flow">
          <div class="first">
          <section class="lead" aria-labelledby="lead-title">
            <div class="spread">
              <div class="say">
                <h1 id="lead-title" class="t-h1">{{ statement[prefs.lang()].title }}</h1>
                <p class="t-muted">{{ statement[prefs.lang()].body }}</p>
              </div>
              <div class="spine" aria-hidden="true"><hw-divider orientation="vertical" /></div>
              <div class="say" [attr.lang]="other()" [attr.dir]="other() === 'ar' ? 'rtl' : 'ltr'">
                <p class="t-h1">{{ statement[other()].title }}</p>
                <p class="t-muted">{{ statement[other()].body }}</p>
              </div>
            </div>
            <div class="install">
              <p class="hw-sr-only">{{ prefs.t('Install with npm', 'التثبيت عبر npm') }}</p>
              <app-code [code]="frameworks[0].install" [copy]="true" [copyName]="prefs.t('npm install command', 'أمر التثبيت')" />
              <div class="install-notes">
                <p class="t-muted t-small">{{ prefs.t('Version 0.2.1, Apache 2.0. This page is rendered with the Angular adapter.', 'الإصدار 0.2.1، برخصة Apache 2.0. هذه الصفحة معروضة بحزمة Angular.') }}</p>
                <p class="t-body"><hw-link href="#install">{{ prefs.t('Steps for React, Vue and JavaScript', 'خطوات React وVue وJavaScript') }}</hw-link></p>
              </div>
            </div>
          </section>

          <section aria-labelledby="duo-title">
            <h2 id="duo-title" class="hw-sr-only">{{ prefs.t('The same composition in two containers', 'التكوين نفسه في حاويتين') }}</h2>
            <div class="duo">
              @for (id of order(); track id; let i = $index) {
                @if (i === 1) {
                  <div class="controls">
                    <div class="controls-head">
                      <h3 class="t-h3">{{ prefs.t('Change one pane', 'تعديل إحدى اللوحتين') }}</h3>
                      <p class="t-muted t-small">{{ prefs.t('Each pane has its own attributes.', 'لكل لوحة سماتها الخاصة.') }}</p>
                    </div>
