  readonly framework = signal('angular');
  readonly panes = signal<Record<PaneId, PaneState>>(this.initial());
  /** The pane in the page language comes first; the other language follows. */
  readonly order = computed<PaneId[]>(() => (this.prefs.lang() === 'ar' ? ['a', 'b'] : ['b', 'a']));
  readonly target = signal<PaneId>(this.prefs.lang() === 'ar' ? 'b' : 'a');
  readonly current = computed(() => this.panes()[this.target()]);
  readonly other = computed<Lang>(() => (this.prefs.lang() === 'ar' ? 'en' : 'ar'));

  readonly langOptions = [{ value: 'ar', label: 'العربية' }, { value: 'en', label: 'English' }];
  readonly targetOptions = computed(() => this.order().map((id) => ({ value: id, label: this.paneName(id) })));
  readonly dirOptions = computed(() => [
    { value: 'rtl', label: this.prefs.t('Right to left', 'من اليمين') },
    { value: 'ltr', label: this.prefs.t('Left to right', 'من اليسار') },
  ]);
  readonly modeOptions = computed(() => [
    { value: 'light', label: this.prefs.t('Light', 'فاتح') },
    { value: 'dark', label: this.prefs.t('Dark', 'داكن') },
  ]);
  readonly densityOptions = computed(() => [
    { value: 'comfortable', label: this.prefs.t('Comfortable', 'مريحة') },
    { value: 'compact', label: this.prefs.t('Compact', 'مضغوطة') },
  ]);
  readonly packages = computed(() => [
    { term: ltr('@hawiyah/tokens'), description: this.prefs.t('Design values and semantic theme variables', 'قيم التصميم والمتغيرات الدلالية للسمات') },
    { term: ltr('@hawiyah/styles'), description: this.prefs.t('Component CSS, layout helpers and a separately imported reset', 'تنسيقات المكوّنات وأدوات التخطيط وملف reset اختياري') },
    { term: ltr('@hawiyah/core'), description: this.prefs.t('Framework-independent behaviour and internationalization helpers', 'منطق مشترك مستقل عن الأطر وأدوات اللغة والتنسيق المحلي') },
    { term: ltr('@hawiyah/vanilla'), description: this.prefs.t('HTML enhancement controllers with cleanup', 'متحكمات تضيف التفاعل إلى HTML مع إتاحة إزالة التفعيل') },
    { term: ltr('@hawiyah/react'), description: this.prefs.t('React components on the shared foundation', 'مكوّنات React على الأساس المشترك') },
    { term: ltr('@hawiyah/vue'), description: this.prefs.t('Vue components on the shared foundation', 'مكوّنات Vue على الأساس المشترك') },
    { term: ltr('@hawiyah/angular'), description: this.prefs.t('Angular components on the shared foundation', 'مكوّنات Angular على الأساس المشترك') },
  ]);
  readonly announcement = signal('');

  constructor() {
    // The page colour mode is the starting point for both panes; a pane can then differ.
    let mode = this.prefs.mode();
    effect(() => {
      const next = this.prefs.mode();
      if (next === mode) return;
      mode = next;
      untracked(() => this.panes.update((all) => ({ a: { ...all.a, mode: next }, b: { ...all.b, mode: next } })));
    });
  }

  paneName(id: PaneId): string { return id === 'a' ? this.prefs.t('Pane A', 'اللوحة أ') : this.prefs.t('Pane B', 'اللوحة ب'); }
  patch(change: Partial<PaneState>): void {
    const id = this.target();
    this.panes.update((all) => ({ ...all, [id]: { ...all[id], ...change } }));
    const now = this.panes()[id];
    this.announcement.set(`${this.paneName(id)}: ${now.lang === 'ar' ? 'العربية' : 'English'}, ${this.label(this.dirOptions(), now.dir)}, ${this.label(this.modeOptions(), now.mode)}, ${this.label(this.densityOptions(), now.density)}`);
  }
  reset(): void {
    this.panes.set(this.initial());
    this.announcement.set(this.prefs.t('Both panes are back to their starting attributes.', 'عادت اللوحتان إلى سماتهما الأولى.'));
  }
  private initial(): Record<PaneId, PaneState> {
    const mode: Mode = this.prefs.mode();
    return { a: { lang: 'ar', dir: 'rtl', mode, density: 'comfortable' }, b: { lang: 'en', dir: 'ltr', mode, density: 'comfortable' } };
  }
  private label(options: readonly { value: string; label: string }[], value: Dir | Mode | Density): string {
    return options.find((option) => option.value === value)?.label ?? value;
  }
}

