import { Component, ElementRef, Injector, afterNextRender, computed, effect, inject, input, signal, untracked } from '@angular/core';
import {
  HwButtonDirective, HwCardComponent, HwDatePickerComponent, HwDescriptionListComponent,
  HwTabComponent, HwTabsComponent, HwTextFieldComponent, type CalendarSystem,
} from '@hawiyah/angular';
import { formatCalendarDate } from '@hawiyah/core';
import type { Dir, Lang, Mode } from './prefs';

export type Density = 'comfortable' | 'compact';
export interface PaneState { lang: Lang; dir: Dir; mode: Mode; density: Density }

const SAMPLE: Record<Lang, string> = { ar: 'سارة أحمد', en: 'Sara Ahmed' };

/** One live composition inside its own lang, dir, mode and density container. */
@Component({
  selector: 'app-pane',
  imports: [HwCardComponent, HwTabsComponent, HwTabComponent, HwTextFieldComponent, HwDatePickerComponent, HwDescriptionListComponent, HwButtonDirective],
  styleUrl: './pane.css',
  template: `
    <figure class="pane">
      <figcaption class="caption">
        <h3 class="t-h3">{{ heading() }}</h3>
        <p class="attrs" lang="en" translate="no">
          <code dir="ltr">lang="{{ state().lang }}" dir="{{ state().dir }}"</code>
          <code dir="ltr">data-hw-mode="{{ state().mode }}"</code>
          <code dir="ltr">data-hw-density="{{ state().density }}"</code>
        </p>
      </figcaption>
      <div class="stage" [attr.lang]="state().lang" [attr.dir]="state().dir" data-hw-theme="dga"
        [attr.data-hw-mode]="state().mode" [attr.data-hw-density]="state().density" [attr.data-rev]="rev()">
        <hw-card variant="outlined">
          <hw-tabs [id]="'pane-' + paneId() + '-tabs'" [label]="t('Appointment request', 'طلب موعد')" [(value)]="tab"
            [direction]="state().dir" [overflowLabel]="t('More tabs', 'المزيد من التبويبات')">
            <hw-tab value="details" [label]="t('Details', 'البيانات')">
              <form class="fields" (submit)="$event.preventDefault(); go('summary')">
                <hw-text-field [controlId]="'pane-' + paneId() + '-name'" name="name" autocomplete="off"
                  [label]="t('Full name', 'الاسم الكامل')" [(value)]="name" />
                <hw-date-picker [controlId]="'pane-' + paneId() + '-date'" name="date" [label]="t('Appointment date', 'تاريخ الموعد')"
                  [locale]="locale()" [direction]="state().dir" [(calendar)]="calendar" [(value)]="date" [hint]="otherLine()" />
                <div><button hwButton variant="primary" type="submit">{{ t('Continue', 'متابعة') }}</button></div>
              </form>
            </hw-tab>
            <hw-tab value="summary" [label]="t('Summary', 'الملخص')">
              <div class="fields">
                <hw-description-list [items]="summary()" />
                <div><button hwButton variant="secondary" type="button" (click)="go('details')">{{ t('Edit', 'تعديل') }}</button></div>
              </div>
            </hw-tab>
          </hw-tabs>
        </hw-card>
      </div>
    </figure>
  `,
})
export class Pane {
  readonly paneId = input.required<'a' | 'b'>();
  readonly heading = input.required<string>();
  readonly state = input.required<PaneState>();
  /** Calendar system the date picker starts with. */
  readonly startCalendar = input<CalendarSystem>('gregory');

  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly injector = inject(Injector);

  readonly tab = signal('details');
  readonly name = signal('');
  readonly date = signal(today());
  readonly calendar = signal<CalendarSystem>('gregory');
  /** Alternates on every change of state so that the transition replays. */
  readonly rev = signal<0 | 1 | null>(null);

  readonly locale = computed(() => (this.state().lang === 'ar' ? 'ar-SA' : 'en-GB'));
  readonly otherLine = computed(() => {
    const other: CalendarSystem = this.calendar() === 'gregory' ? 'islamic-umalqura' : 'gregory';
    const text = this.format(other);
    return text ? `\u2068${this.calendarName(other)}: ${text}\u2069` : this.t('Enter a date as YYYY-MM-DD or open the calendar.', 'أدخل التاريخ بصيغة YYYY-MM-DD أو افتح التقويم.');
  });
  readonly summary = computed(() => [
    { term: this.t('Full name', 'الاسم الكامل'), description: this.name().trim() || '—' },
    { term: this.calendarName('islamic-umalqura'), description: this.format('islamic-umalqura') || '—' },
    { term: this.calendarName('gregory'), description: this.format('gregory') || '—' },
    { term: this.t('Stored value (ISO 8601)', 'القيمة المحفوظة (ISO 8601)'), description: this.date() ? `⁦${this.date()}⁩` : '—' },
  ]);

  constructor() {
    let first = true;
    let previous: PaneState | undefined;
    effect(() => {
      const next = this.state();
      untracked(() => {
        if (first) { this.calendar.set(this.startCalendar()); this.name.set(SAMPLE[next.lang]); first = false; }
        else {
          if (previous && previous.lang !== next.lang && this.name() === SAMPLE[previous.lang]) this.name.set(SAMPLE[next.lang]);
          this.rev.update((value) => (value === 0 ? 1 : 0));
        }
        previous = next;
      });
    });
  }

  t(en: string, ar: string): string { return this.state().lang === 'ar' ? ar : en; }
  calendarName(system: CalendarSystem): string {
    return system === 'gregory' ? this.t('Gregorian', 'الميلادي') : this.t('Umm al-Qura', 'أم القرى');
  }
  format(system: CalendarSystem): string {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(this.date())) return '';
    // First-strong isolate: the date keeps its own order when the pane's direction differs from its language.
    try { return `\u2068${formatCalendarDate(this.date(), { locale: this.locale(), calendar: system, dateStyle: 'long' })}\u2069`; } catch { return ''; }
  }
  /** Change tab from a button inside a panel, then put focus on the tab that now owns the visible panel. */
  go(tab: 'details' | 'summary'): void {
    this.tab.set(tab);
    afterNextRender(() => this.host.nativeElement.querySelector<HTMLElement>('[role="tab"][aria-selected="true"]')?.focus(), { injector: this.injector });
  }
}

function today(): string {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
}

