// Drive the pane controls and record what happens. Called by probe.cjs with (page, outPrefix).
module.exports = async (page, out) => {
  const log = (k, v) => console.log(k, JSON.stringify(v));
  const stageOf = (id) => page.locator(`#pane-${id}-name`).locator('xpath=ancestor::div[contains(@class,"stage")]');
  const attrs = async (id) => stageOf(id).evaluate((n) => ({ lang: n.lang, dir: n.dir, mode: n.dataset.hwMode, density: n.dataset.hwDensity, rev: n.dataset.rev, bg: getComputedStyle(n.querySelector('article')).backgroundColor, anim: getComputedStyle(n).animationName }));
  const target = await page.locator('#duo-target, fieldset').first().evaluate(() => [...document.querySelectorAll('fieldset')].map((f) => f.querySelector('legend').textContent + ': ' + [...f.querySelectorAll('input')].find((i) => i.checked)?.value));
  log('controls', target);
  // choose pane B, then English + RTL + dark + compact
  const pick = async (legendIndex, value) => page.evaluate(([i, v]) => { const f = document.querySelectorAll('.controls fieldset')[i]; f.querySelector(`input[value="${v}"]`).click(); }, [legendIndex, value]);
  await pick(0, 'b'); await pick(2, 'rtl');
  log('b after rtl', await attrs('b'));
  await page.waitForTimeout(50);
  log('running animations right after change', await page.evaluate(() => document.getAnimations().map((a) => a.animationName + ':' + a.playState)));
  await page.waitForTimeout(500);
  await pick(3, 'dark'); await pick(4, 'compact');
  await page.waitForTimeout(500);
  log('b after dark+compact', await attrs('b'));
  log('a untouched', await attrs('a'));
  log('status', await page.locator('.controls [role=status]').textContent());
  if (out) await page.locator('.duo').screenshot({ path: out + '.duo.png' });
  // tabs: Continue moves to summary and focuses the tab
  await page.locator('#pane-b-name').locator('xpath=ancestor::form').locator('button[type=submit]').click();
  await page.waitForTimeout(200);
  log('focus after continue', await page.evaluate(() => ({ role: document.activeElement.getAttribute('role'), text: document.activeElement.textContent.trim(), selected: document.activeElement.getAttribute('aria-selected') })));
  log('summary', await stageOf('b').locator('dl').innerText());
  // date picker dialog inherits pane attributes
  await page.locator('#pane-a-date').locator('xpath=following-sibling::button').click();
  await page.waitForTimeout(300);
  log('dialog', await page.evaluate(() => { const d = document.querySelector('dialog[open]'); return d && { dir: getComputedStyle(d).direction, title: d.querySelector('h2,h3,[id$=title]')?.textContent, system: [...d.querySelectorAll('input[type=radio]')].find((i) => i.checked)?.value }; }));
  if (out) await page.screenshot({ path: out + '.dialog.png' });
  await page.keyboard.press('Escape');
  // language of pane B to Arabic swaps the sample name
  await pick(1, 'ar'); await page.waitForTimeout(300);
  log('b name after ar', await page.locator('#pane-b-name').inputValue());
  // header controls
  await page.locator('#page-dark').click(); await page.waitForTimeout(200);
  log('page dark', await page.evaluate(() => ({ mode: document.documentElement.dataset.hwMode, url: location.search, a: document.querySelector('#pane-a-name').closest('.stage').dataset.hwMode })));
  await page.locator('a[href="#install"]').click(); await page.waitForTimeout(300);
  log('after anchor', await page.evaluate(() => ({ url: location.pathname + location.search + location.hash, mode: document.documentElement.dataset.hwMode, scrolled: scrollY > 200 })));
  await page.evaluate(() => scrollTo(0, 0));
  await page.keyboard.press('Tab');
  log('first tab stop', await page.evaluate(() => ({ text: document.activeElement.textContent.trim(), href: document.activeElement.getAttribute('href') })));
  await page.keyboard.press('Enter'); await page.waitForTimeout(300);
  log('after skip', await page.evaluate(() => ({ url: location.pathname + location.search + location.hash, mode: document.documentElement.dataset.hwMode, lang: document.documentElement.lang })));
};

