// Serve the build and run ad-hoc checks. Usage: node probe.cjs <query> <width> [action]
const { chromium } = require('<node-tools>/node_modules/playwright');
const fs = require('node:fs'), path = require('node:path'), http = require('node:http');
const dist = path.join(__dirname, '../dist/base/browser');
const types = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml', '.woff2': 'font/woff2', '.woff': 'font/woff', '.ico': 'image/x-icon' };
const server = http.createServer((req, res) => { const u = new URL(req.url, 'http://x'); let f = path.join(dist, decodeURIComponent(u.pathname)); if (!fs.existsSync(f) || fs.statSync(f).isDirectory()) f = path.join(dist, 'index.html'); res.setHeader('content-type', types[path.extname(f)] || 'application/octet-stream'); res.end(fs.readFileSync(f)); });
const [, , query = '?lang=ar', width = '390', action = 'overflow', out = ''] = process.argv;
(async () => {
  await new Promise((r) => server.listen(4531, '127.0.0.1', r));
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ viewport: { width: Number(width), height: 900 }, reducedMotion: action.includes('motion') ? 'no-preference' : 'reduce' });
  const page = await ctx.newPage();
  const errors = []; page.on('pageerror', (e) => errors.push(String(e))); page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto('http://127.0.0.1:4531/' + query, { waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  if (action === 'overflow') {
    console.log(JSON.stringify(await page.evaluate(() => { const w = document.documentElement.clientWidth; return { overflow: document.documentElement.scrollWidth - w, wide: [...document.querySelectorAll('body *')].filter((n) => { const r = n.getBoundingClientRect(); return r.width > 0 && (r.right > w + 1 || r.left < -1); }).slice(0, 14).map((n) => `${n.tagName.toLowerCase()}.${String(n.className).slice(0, 40)} [${Math.round(n.getBoundingClientRect().left)},${Math.round(n.getBoundingClientRect().right)}]`) }; }), null, 1));
  }
  if (action === 'small') {
    console.log(JSON.stringify(await page.evaluate(() => [...document.querySelectorAll('a[href],button,input:not([type=hidden]),select,summary,[role=tab]')].filter((n) => { const r = n.getBoundingClientRect(); return r.width > 0 && r.height > 0 && (r.width < 24 || r.height < 24); }).map((n) => `${n.tagName.toLowerCase()}.${String(n.className).slice(0, 30)} ${n.type || ''} ${Math.round(n.getBoundingClientRect().width)}x${Math.round(n.getBoundingClientRect().height)} "${(n.textContent || '').trim().slice(0, 30)}" parent=${n.parentElement.tagName.toLowerCase()} ${Math.round(n.parentElement.getBoundingClientRect().width)}x${Math.round(n.parentElement.getBoundingClientRect().height)}`)), null, 1));
  }
  if (action.startsWith('script:')) { const fn = require(path.resolve(action.slice(7))); await fn(page, out); }
  if (out && !action.startsWith('script:')) await page.screenshot({ path: out, fullPage: true });
  if (errors.length) console.log('ERRORS', errors.slice(0, 5));
  await browser.close(); server.close();
})().catch((e) => { console.error(e); process.exit(1); });

