// Screenshot the page in viewport-height segments: out is a prefix.
module.exports = async (page, out) => {
  const total = await page.evaluate(() => document.documentElement.scrollHeight);
  const h = page.viewportSize().height; let i = 0;
  for (let y = 0; y < total; y += h) { await page.evaluate((v) => scrollTo(0, v), y); await page.waitForTimeout(120); await page.screenshot({ path: `${out}.${i++}.png` }); }
  console.log('segments', i, 'height', total);
};

